template.template_css:
.table-header {
    background-color: #0f172a;
    color: #ffffff;
}
.badge {
    background-color: #e2e8f0;
    border-radius: 9999px;
    padding: 0.1rem 0.75rem;
    font-size: 0.875rem;
}
.disk-pill {
    background-color: #f8fafc;
    border: 1px solid #cbd5f5;
    border-radius: 9999px;
    padding: 0.15rem 0.75rem;
    display: inline-block;
    margin: 0.15rem;
}

template.template_md:
{% block content %}
<div class="max-w-6xl mx-auto py-10 px-6">
  <div class="bg-white rounded-xl shadow-lg p-6 mb-8">
    <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
      <div>
        <p class="text-sm uppercase tracking-wide text-slate-500">Client</p>
        <h1 class="text-3xl font-semibold text-slate-800">{{ client.name }}</h1>
      </div>
      <div class="text-right">
        <p class="text-sm text-slate-500">Report generated</p>
        <p class="text-lg font-medium text-slate-800">{{ report_run_timestamp.strftime('%Y-%m-%d %H:%M') if report_run_timestamp else '' }}</p>
      </div>
    </div>
    <p class="mt-4 text-slate-600">Overview of enrolled systems showing the device name, hardware model, installed memory, and disk utilization for the selected client.</p>
  </div>

  {% if data_sources.agents %}
  <div class="overflow-x-auto bg-white shadow-lg rounded-xl">
    <table class="min-w-full divide-y divide-slate-200">
      <thead class="table-header">
        <tr>
          <th class="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider">System Name</th>
          <th class="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider">System Model</th>
          <th class="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider">Installed Memory (GB)</th>
          <th class="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider">Disk Usage (Used / Total)</th>
        </tr>
      </thead>
      <tbody class="divide-y divide-slate-100">
        {% for item in data_sources.agents %}
        {% set model_value = 'N/A' %}
        {% if item.wmi_detail and item.wmi_detail.comp_sys and item.wmi_detail.comp_sys[0] and item.wmi_detail.comp_sys[0][0] and item.wmi_detail.comp_sys[0][0].Model %}
          {% set model_value = item.wmi_detail.comp_sys[0][0].Model %}
        {% endif %}
        <tr class="hover:bg-slate-50">
          <td class="px-4 py-4 text-sm font-medium text-slate-900">{{ item.hostname if item.hostname else 'N/A' }}</td>
          <td class="px-4 py-4 text-sm text-slate-700">{{ model_value }}</td>
          <td class="px-4 py-4 text-sm text-slate-700">{{ item.total_ram if item.total_ram else 'N/A' }}</td>
          <td class="px-4 py-4 text-sm text-slate-700">
            {% if item.disks %}
              {% for disk in item.disks %}
                {% if disk.device or disk.used or disk.total %}
                  <span class="disk-pill">{{ disk.device if disk.device else 'Disk' }}: {{ disk.used if disk.used else 'N/A' }} / {{ disk.total if disk.total else 'N/A' }}</span>
                {% endif %}
              {% else %}
              <span class="badge">N/A</span>
              {% endfor %}
            {% else %}
            <span class="badge">N/A</span>
            {% endif %}
          </td>
        </tr>
        {% else %}
        <tr>
          <td colspan="4" class="px-4 py-6 text-center text-sm text-slate-500">No systems were found for the selected client.</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
  {% else %}
  <div class="bg-white rounded-xl shadow p-6 text-center text-slate-500">No systems were found for the selected client.</div>
  {% endif %}
</div>
{% endblock %}
